// Package probe reads the container metadata of the supported MXF and MP4
// subsets and converts it to the unified model. Probing never decodes media;
// it only records structure, timing and descriptive metadata.
package probe

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"sort"
	"strings"

	"archive/internal/fault"
	"archive/internal/model"
)

// Source is one input file held in memory. Fixtures are generated by the
// project, so a bounded in-memory source keeps offsets unambiguous and makes
// damaged inputs cheap to re-probe.
type Source struct {
	Name string
	Data []byte
}

// File is the probe result for one container.
type File struct {
	Container  model.ContainerKind `json:"container"`
	Path       string              `json:"path"`
	Size       uint64              `json:"size_bytes"`
	SHA256     string              `json:"sha256"`
	Tracks     []*model.Track      `json:"tracks"`
	Faults     fault.List          `json:"-"`
	Info       map[string]string   `json:"info,omitempty"`
	Partitions int                 `json:"partitions,omitempty"`
}

// Digest returns the hex SHA-256 of the input. It is the identity used by the
// checkpoint, so a changed input can never resume a previous run.
func (s Source) Digest() string {
	sum := sha256.Sum256(s.Data)
	return hex.EncodeToString(sum[:])
}

// Probe dispatches on the container format.
func Probe(src Source, container model.ContainerKind) (*File, error) {
	var (
		f   *File
		err error
	)
	switch container {
	case model.ContainerMP4:
		f, err = ProbeMP4(src)
	case model.ContainerMXF:
		f, err = ProbeMXF(src)
	default:
		return nil, fmt.Errorf("probe: unsupported container %q", container)
	}
	if err != nil {
		return nil, err
	}
	f.SHA256 = src.Digest()
	assignLogical(f.Tracks)
	sort.Slice(f.Tracks, func(i, j int) bool {
		if f.Tracks[i].Logical != f.Tracks[j].Logical {
			return f.Tracks[i].Logical < f.Tracks[j].Logical
		}
		return f.Tracks[i].TrackID < f.Tracks[j].TrackID
	})
	faults := f.Faults.Dedup()
	f.Faults = faults
	return f, nil
}

// assignLogical gives each track a container-independent identity so the
// mapper can join the several container versions of one archived reel. The
// media kind is the natural join key; when a container carries more than one
// track of a kind the track id disambiguates it.
func assignLogical(tracks []*model.Track) {
	counts := make(map[model.TrackKind]int, len(tracks))
	for _, t := range tracks {
		counts[t.Kind]++
	}
	for _, t := range tracks {
		base := string(t.Kind)
		if counts[t.Kind] > 1 {
			t.Logical = fmt.Sprintf("%s#%d", base, t.TrackID)
		} else {
			t.Logical = base
		}
	}
}

// TrackKey is the canonical per-container identity of a track.
func TrackKey(container model.ContainerKind, trackID uint32) string {
	return fmt.Sprintf("%s/t%d", container, trackID)
}

// colorCodeName maps a CICP code point to the canonical fixture vocabulary.
// Unknown codes are rendered numerically so no information is lost.
func colorPrimariesName(v uint16) string {
	switch v {
	case 1:
		return "bt709"
	case 9:
		return "bt2020"
	case 12:
		return "smpte432"
	}
	return fmt.Sprintf("code%d", v)
}

func colorTransferName(v uint16) string {
	switch v {
	case 1:
		return "bt709"
	case 16:
		return "smpte2084"
	case 18:
		return "hlg"
	}
	return fmt.Sprintf("code%d", v)
}

func colorMatrixName(v uint16) string {
	switch v {
	case 1:
		return "bt709"
	case 9:
		return "bt2020nc"
	}
	return fmt.Sprintf("code%d", v)
}

// rotationFromMatrix recovers the display rotation from a tkhd/track matrix.
// Only the four axis-aligned cases are meaningful for the supported subset.
func rotationFromMatrix(m [9]int32) int {
	// Column vectors: (a,b) is the transformed x axis, (c,d) the y axis.
	a, b := m[0], m[1]
	switch {
	case a > 0 && b == 0:
		return 0
	case a == 0 && b > 0:
		return 90
	case a < 0 && b == 0:
		return 180
	case a == 0 && b < 0:
		return 270
	}
	return 0
}

// description builds the resolved, single-source colour view for a container.
// Cross-container arbitration happens later in the mapper; here the values
// and their source are recorded verbatim.
func description(primaries, transfer, matrix, rng, source string) model.ColorDescription {
	return model.ColorDescription{
		Primaries:    model.ColorField{Field: "primaries", Value: primaries, Source: source},
		Transfer:     model.ColorField{Field: "transfer", Value: transfer, Source: source},
		Matrix:       model.ColorField{Field: "matrix", Value: matrix, Source: source},
		Range:        model.ColorField{Field: "range", Value: rng, Source: source},
		ArbitratedBy: source,
	}
}

// claims flattens a colour description into auditable per-field claims.
func claims(d model.ColorDescription) []model.ColorField {
	return []model.ColorField{d.Primaries, d.Transfer, d.Matrix, d.Range}
}

// DescribeFaults renders faults for terminal output without duplicating the
// fault package formatting.
func DescribeFaults(l fault.List) []string {
	lines := make([]string, 0, len(l))
	for _, e := range l {
		lines = append(lines, e.Line())
	}
	return lines
}

// LogicalOf returns the logical name of a probed track key.
func (f *File) LogicalOf(key string) string {
	for _, t := range f.Tracks {
		if t.Key == key {
			return t.Logical
		}
	}
	return key
}

// String is a compact human summary used in tests and logs.
func (f *File) String() string {
	var b strings.Builder
	fmt.Fprintf(&b, "%s tracks=%d size=%d", f.Container, len(f.Tracks), f.Size)
	for _, t := range f.Tracks {
		fmt.Fprintf(&b, " [%s id=%d %s@%d]", t.Logical, t.TrackID, t.Kind, t.Timebase.Timescale)
	}
	return b.String()
}
